) */
//@formatter:on
public class ValidateProgramPlugin : Plugin {
	public static string PLUGIN_NAME = "ValidateProgramPlugin";
	public static string ACTION_NAME = "Validate Program";

	private DockingAction validateAction;

	public ValidateProgramPlugin(PluginTool tool) : base(tool)
    {
	}

	/* @Override */
	protected void init() {
		setupActions();
	}

	/* @Override */
	public void dispose() {
		tool.removeAction(validateAction);
		validateAction.dispose();
		base.dispose();
	}

	private void setupActions() {
		validateAction = new _Anon_ProgramContextAction_1(ACTION_NAME, PLUGIN_NAME);
		validateAction.addToWindowWhen(typeof(ListingActionContext));
		validateAction.setMenuBarData(new MenuData(new string[] { ToolConstants.MENU_ANALYSIS,
			ACTION_NAME }, null, "ZZZ"));

		validateAction.setEnabled(false);

		validateAction.setHelpLocation(new HelpLocation("ValidateProgram", "top_of_page"));
		validateAction.setDescription(getPluginDescription().getDescription());
		tool.addAction(validateAction);
	}

	private void validate(Program program) {
		List<ConditionTester> list = getConditionTests(program);
		Collections.sort(list, new ConditionsComparator());
		ValidateProgramDialog dialog = new ValidateProgramDialog(program, list);
		tool.showDialog(dialog);
	}

	private List<ConditionTester> getConditionTests(Program program) {
		List<ConditionTester> list = new List<ConditionTester>();

		List<Class<PostAnalysisValidator>> validatorClasses =
			ClassSearcher.getClasses(typeof(PostAnalysisValidator));
		foreach (Class<PostAnalysisValidator> validatorClass in validatorClasses) {
			try {
				Constructor<PostAnalysisValidator> ctor =
					validatorClass.getConstructor(typeof(Program));
				PostAnalysisValidator validator = ctor.newInstance(program);
				list.add(validator);
			}
			catch (Exception e) {
				Msg.error(this, "error including PostAnalysisValidator " + validatorClass, e);
			}
		}
		return list;
	}

	private class ConditionsComparator : Comparator<ConditionTester> {
		/* @Override */
		public int compare(ConditionTester o1, ConditionTester o2) {
			return o1.getName().compareTo(o2.getName());
		}
	}

	internal class _Anon_ProgramContextAction_1 : ProgramContextAction
	{
		public _Anon_ProgramContextAction_1() : @base(ACTION_NAME, PLUGIN_NAME) {}

			/* @Override */
			public void actionPerformed(ProgramActionContext context) {
				Program program = context.getProgram();
				validate(program);
			}

			/* @Override */
			public bool isEnabledForContext(ActionContext context) {
				if (!base.isEnabledForContext(context)) {
					getMenuBarData().setMenuItemName(ACTION_NAME);
					return false;
				}
				return true;
			}

			/* @Override */
			public bool isEnabledForContext(ProgramActionContext context) {
				Program program = context.getProgram();
				string menuName = "Validate " + program.getDomainFile().getName();
				getMenuBarData().setMenuItemName(menuName);
				return true;
			}
		
	}

}
